class ClaudeRelay < Formula
  desc "Use several Claude subscriptions as one: account failover and session migration"
  homepage "https://github.com/guedesdiogo/claude-relay"
  url "https://github.com/guedesdiogo/claude-relay/archive/refs/tags/v2.2.1.tar.gz"
  sha256 "bd17bd2e02543dac4ea7a2be4b3bcf2c5eff852b638355bc14b8dc2f251bfffd"
  license "MIT"
  head "https://github.com/guedesdiogo/claude-relay.git", branch: "main"

  uses_from_macos "python"

  def install
    bin.install "bin/claude-relay"
    # The command used up to 1.x keeps working and forwards to `claude-relay desktop`.
    bin.install "bin/claude-session-restorer"
  end

  test do
    assert_match "claude-relay #{version}", shell_output("#{bin}/claude-relay --version")
    ENV["HOME"] = testpath
    ENV["CLAUDE_RELAY_TOKEN_STORE"] = "file"
    pipe_output("#{bin}/claude-relay accounts add test", "sk-ant-oat01-#{"x" * 40}\n", 0)
    assert_match "test", shell_output("#{bin}/claude-relay accounts list")
  end
end
